{
  "correction_rules": [
    "Reduce forecast overshoots following sharp price spikes (e.g., >70% above recent mean) by 10-20% to avoid overreaction.",
    "Adjust forecasts downward when sentiment history shows negative sentiment (e.g., -0.20 or below) for 3-5 consecutive days, indicating bearish momentum.",
    "Apply mean reversion bias: if forecast is >15% above 30-day moving average, reduce by 5-10% for next period; if below -15%, increase by 5-10%.",
    "Lag correction: if true outcome is significantly lower than forecast (e.g., >10% below), reduce next forecast by 5-10% to account for delayed market reaction.",
    "Increase forecast sensitivity to sentiment shifts: if sentiment turns positive (e.g., +0.33 or above) after a downtrend, raise forecast by 5-10% to capture momentum.",
    "Avoid overfitting to recent highs: if last 5 days show rising prices, cap forecast increase to 5% max to prevent runaway inflation in price expectations."
  ]
}
